/// <summary>The relay's own WebSocket close codes (plan-relay S1); never the app's 4001–4007.</summary>
public static class RelayCloseCodes
{
    /// <summary>Relay protocol error: a frame the relay does not accept here (e.g. dialer data before RELAY_STREAM_OPEN).</summary>
    public const int ProtocolError = 4500;

    /// <summary>Dial token refused; only ever sent for a relayId that is online.</summary>
    public const int DialRefused = 4501;

    /// <summary>RELAY_REGISTER proof invalid (signature, nonce or host).</summary>
    public const int RegistrationInvalid = 4503;

    /// <summary>relayId not online, or unknown / expired streamId; checked before the token.</summary>
    public const int NotOnline = 4504;

    /// <summary>Control socket replaced by a newer registration of the same relayId.</summary>
    public const int Replaced = 4507;

    /// <summary>The extension did not accept the stream within 15 s.</summary>
    public const int AcceptTimeout = 4508;

    /// <summary>A stream of that kind is already open for that relayId.</summary>
    public const int SlotTaken = 4509;

    /// <summary>Frame over 512 KiB.</summary>
    public const int FrameTooLarge = 4513;

    /// <summary>Quota of that relayId used up; reason = retry-after seconds (decimal).</summary>
    public const int QuotaExceeded = 4529;

    /// <summary>The dialer's IP is over its refused-dial / registration limit; reason = retry-after seconds. Never a Chrome's quota.</summary>
    public const int DialerLimited = 4530;
}

/// <summary>Error object (spec §35, §71.8).</summary>
public sealed record PandaError(
    [property: JsonPropertyName("code")] ErrorCode Code,
    [property: JsonPropertyName("message")] string Message,
