    public const string TypeName = "RELAY_ROTATE";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>extension -> relay, URL-only mode: revoke this Chrome's MCP token and unpair it from the hosted bridge. Idempotent.</summary>
public sealed record RelayUnhost(
    [property: JsonPropertyName("seq")] long Seq) : IRelayMessage
{
    public const string TypeName = "RELAY_UNHOST";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>relay -> extension: the outcome of the RELAY_HOST / RELAY_ROTATE / RELAY_UNHOST with this seq. Never echoes the code or the token hash.</summary>
public sealed record RelayHostResult(
    [property: JsonPropertyName("seq")] long Seq,
    [property: JsonPropertyName("ok")] bool Ok,
    [property: JsonPropertyName("mcpUrl"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? McpUrl = null,
    [property: JsonPropertyName("error"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] RelayHostError? Error = null) : IRelayMessage
{
    public const string TypeName = "RELAY_HOST_RESULT";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>A key with modifiers, protocol ≥ 8 (plan-phase8 D1, D4): the bridge sends one only when the pair is not one of the 20 KeyNames.</summary>
public sealed record KeyChord(
    [property: JsonPropertyName("code")] string Code,
    [property: JsonPropertyName("modifiers")] long Modifiers);

/// <summary>One download a page began while Panda was attached to it (plan-downloads AC1, D1, D6). path = Chrome's full local path once chosen (while in progress the bytes are in a .crdownload beside it); an optional field is omitted when Chrome's value is empty or does not fit.</summary>
public sealed record DownloadInfo(
    [property: JsonPropertyName("downloadRef")] string DownloadRef,
    [property: JsonPropertyName("url")] string Url,
    [property: JsonPropertyName("suggestedFilename")] string SuggestedFilename,
    [property: JsonPropertyName("state")] DownloadState State,
    [property: JsonPropertyName("receivedBytes")] long ReceivedBytes,
    [property: JsonPropertyName("startedAt")] long StartedAt,
    [property: JsonPropertyName("path"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? Path = null,
    [property: JsonPropertyName("totalBytes"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? TotalBytes = null,
    [property: JsonPropertyName("mime"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? Mime = null,
    [property: JsonPropertyName("danger"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? Danger = null,
    [property: JsonPropertyName("error"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? Error = null,
    [property: JsonPropertyName("endedAt"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? EndedAt = null);

/// <summary>Bridge → extension, protocol ≥ 9: the page's downloads, newest first (plan-downloads AC1). A read: answered without attaching.</summary>
public sealed record CmdDownloads(
    [property: JsonPropertyName("requestId")] string RequestId,
    [property: JsonPropertyName("pageId")] string PageId) : IMessage
{
    public const string TypeName = "CMD_DOWNLOADS";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>Extension → bridge: answer to CMD_DOWNLOADS — at most 20, newest first (plan-downloads AC1).</summary>
public sealed record DownloadsResult(
    [property: JsonPropertyName("requestId")] string RequestId,
    [property: JsonPropertyName("watchId")] string WatchId,
    [property: JsonPropertyName("downloads")] IReadOnlyList<DownloadInfo> Downloads) : IMessage
{
    public const string TypeName = "DOWNLOADS_RESULT";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>Bridge → extension, protocol ≥ 9: wait until the target download is no longer in progress or timeoutMs passes (plan-downloads AC2, D7). Target: downloadRef; or the first download newer than after; or neither = the first the page began after its latest download-capable command (and after the last one a wait returned). At most one of downloadRef / after is the bridge's check; the extension re-checks it.</summary>
public sealed record CmdWaitDownload(
    [property: JsonPropertyName("requestId")] string RequestId,
    [property: JsonPropertyName("pageId")] string PageId,
    [property: JsonPropertyName("timeoutMs")] long TimeoutMs,
    [property: JsonPropertyName("downloadRef"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? DownloadRef = null,
    [property: JsonPropertyName("after"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? After = null) : IMessage
{
    public const string TypeName = "CMD_WAIT_DOWNLOAD";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>Extension → bridge: answer to CMD_WAIT_DOWNLOAD. matched = the target is complete or interrupted; at the timeout matched false, with the target's current state when there is one, without download when none began (plan-downloads AC2).</summary>
public sealed record DownloadWaitResult(
    [property: JsonPropertyName("requestId")] string RequestId,
    [property: JsonPropertyName("watchId")] string WatchId,
    [property: JsonPropertyName("matched")] bool Matched,
    [property: JsonPropertyName("elapsedMs")] long ElapsedMs,
    [property: JsonPropertyName("download"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] DownloadInfo? Download = null) : IMessage
{
    public const string TypeName = "DOWNLOAD_WAIT_RESULT";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>Integers on the wire (plan-netemu D2a): the bridge converts the tool's decimal degrees and metres.</summary>
public sealed record EmulatedGeolocation(
    [property: JsonPropertyName("latitudeE6")] long LatitudeE6,
    [property: JsonPropertyName("longitudeE6")] long LongitudeE6,
    [property: JsonPropertyName("accuracyMeters"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? AccuracyMeters = null);

/// <summary>The whole wanted emulation of a page (plan-netemu D3: replace, not merge; {} = clear all); in OVERRIDES_RESULT the confirmed fields. acceptLanguage only with userAgent is the bridge's check; the extension re-checks it.</summary>
public sealed record Emulation(
    [property: JsonPropertyName("userAgent"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? UserAgent = null,
    [property: JsonPropertyName("acceptLanguage"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? AcceptLanguage = null,
    [property: JsonPropertyName("touch"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] bool? Touch = null,
    [property: JsonPropertyName("deviceScalePercent"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? DeviceScalePercent = null,
    [property: JsonPropertyName("colorScheme"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] ColorScheme? ColorScheme = null,
    [property: JsonPropertyName("geolocation"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] EmulatedGeolocation? Geolocation = null,
    [property: JsonPropertyName("timezone"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? Timezone = null,
    [property: JsonPropertyName("locale"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? Locale = null);

/// <summary>A request header (headers rule) or a response header (mock rule); the refused names (plan-netemu D4) are the bridge's check, re-checked by the extension.</summary>
public sealed record RuleHeader(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("value")] string Value);

/// <summary>One rule; the first matching rule acts (plan-netemu D4). Per action (headers: 1..20 headers, nothing else; mock: at most one of body / bodyBase64, decoded ≤ 1 000 000 bytes, ≤ 4 000 000 over the call; block: neither) is the bridge's check, re-checked by the extension.</summary>
public sealed record NetworkRule(
    [property: JsonPropertyName("urlPattern")] string UrlPattern,
    [property: JsonPropertyName("action")] RuleAction Action,
    [property: JsonPropertyName("headers"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] IReadOnlyList<RuleHeader>? Headers = null,
    [property: JsonPropertyName("status"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? Status = null,
    [property: JsonPropertyName("body"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? Body = null,
    [property: JsonPropertyName("bodyBase64"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? BodyBase64 = null);

/// <summary>Network.emulateNetworkConditions (plan-netemu D5); at least one field is the bridge's check.</summary>
public sealed record NetworkConditions(
    [property: JsonPropertyName("offline"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] bool? Offline = null,
    [property: JsonPropertyName("latencyMs"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? LatencyMs = null,
    [property: JsonPropertyName("downloadKbps"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? DownloadKbps = null,
    [property: JsonPropertyName("uploadKbps"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? UploadKbps = null);

/// <summary>The size page_resize put in force (CSS px).</summary>
public sealed record OverridesViewport(
    [property: JsonPropertyName("width")] long Width,
    [property: JsonPropertyName("height")] long Height);

/// <summary>A rule in force: names and sizes only, never a header value or a body (plan-netemu D13, AC12).</summary>
public sealed record RuleState(
    [property: JsonPropertyName("urlPattern")] string UrlPattern,
    [property: JsonPropertyName("action")] RuleAction Action,
    [property: JsonPropertyName("hits")] long Hits,
    [property: JsonPropertyName("headerNames"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] IReadOnlyList<string>? HeaderNames = null,
    [property: JsonPropertyName("status"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? Status = null,
    [property: JsonPropertyName("bodyBytes"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] long? BodyBytes = null);

/// <summary>Bridge → extension, protocol ≥ 10: put exactly this emulation in force on the page (plan-netemu AC5, AC6, D3); answered by OVERRIDES_RESULT.</summary>
public sealed record CmdEmulate(
    [property: JsonPropertyName("requestId")] string RequestId,
    [property: JsonPropertyName("pageId")] string PageId,
    [property: JsonPropertyName("emulation")] Emulation Emulation) : IMessage
{
    public const string TypeName = "CMD_EMULATE";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>Bridge → extension, protocol ≥ 10: put exactly these rules and conditions in force on the page (plan-netemu AC1–AC4, AC6); rules [] and no conditions = clear. Answered by OVERRIDES_RESULT.</summary>
public sealed record CmdNetworkRules(
    [property: JsonPropertyName("requestId")] string RequestId,
    [property: JsonPropertyName("pageId")] string PageId,
    [property: JsonPropertyName("rules")] IReadOnlyList<NetworkRule> Rules,
    [property: JsonPropertyName("conditions"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] NetworkConditions? Conditions = null) : IMessage
{
    public const string TypeName = "CMD_NETWORK_RULES";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>Bridge → extension, protocol ≥ 10: what is in force on the page (plan-netemu AC8). A read: answered without attaching.</summary>
public sealed record CmdOverrides(
    [property: JsonPropertyName("requestId")] string RequestId,
    [property: JsonPropertyName("pageId")] string PageId) : IMessage
{
    public const string TypeName = "CMD_OVERRIDES";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

/// <summary>Extension → bridge: answer to CMD_EMULATE, CMD_NETWORK_RULES and CMD_OVERRIDES — the state Chrome confirmed (plan-netemu D13); a part in unknown shows its last confirmed value.</summary>
public sealed record OverridesResult(
    [property: JsonPropertyName("requestId")] string RequestId,
    [property: JsonPropertyName("emulation")] Emulation Emulation,
    [property: JsonPropertyName("rules")] IReadOnlyList<RuleState> Rules,
    [property: JsonPropertyName("viewport"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] OverridesViewport? Viewport = null,
    [property: JsonPropertyName("conditions"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] NetworkConditions? Conditions = null,
    [property: JsonPropertyName("unknown"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] IReadOnlyList<OverridePart>? Unknown = null) : IMessage
{
    public const string TypeName = "OVERRIDES_RESULT";

    [JsonPropertyName("type")]
    public string Type => TypeName;
}

