internal static partial class ProtocolValidation
{
    public static string? FirstViolation(object? value) => value switch
    {
        null => "null value",
        PandaError x => Str(x.Message, null, 1024, "message")
            ?? Str(x.SuggestedAction, null, 64, "suggestedAction")
            ?? (x.Dialog is null ? null : FirstViolation(x.Dialog)),
        Page x => Str(x.PageId, P0, null, "pageId")
            ?? Int(x.WindowId, null, null, "windowId")
            ?? Int(x.Index, null, null, "index")
            ?? Str(x.Url, null, 2048, "url")
            ?? Str(x.Title, null, 256, "title")
            ?? Str(x.OpenerPageId, P0, null, "openerPageId"),
        BrowserMetadata x => Str(x.BrowserName, null, 64, "browserName")
            ?? Str(x.ProfileName, null, 128, "profileName")
            ?? Str(x.ExtensionVersion, null, 32, "extensionVersion"),
        BrowserInfo x => Str(x.BrowserId, P1, null, "browserId")
            ?? Str(x.Name, null, 64, "name")
            ?? Str(x.ProfileName, null, 128, "profileName")
            ?? Str(x.ExtensionVersion, null, 32, "extensionVersion")
            ?? Str(x.ConnectedAt, null, 40, "connectedAt"),
        Hello x => Int(x.ProtocolVersion, null, null, "protocolVersion")
            ?? Str(x.BrowserInstanceId, P1, null, "browserInstanceId")
            ?? Str(x.ExtensionVersion, null, 32, "extensionVersion")
            ?? Str(x.ExtNonce, P2, null, "extNonce"),
        Challenge x => Str(x.BridgeNonce, P2, null, "bridgeNonce")
            ?? Str(x.BridgeProof, P3, null, "bridgeProof"),
        Auth x => Str(x.ExtProof, P3, null, "extProof"),
        Accept x => null,
        RegisterBrowser x => FirstViolation(x.Metadata)
            ?? Each(x.Pages, 1000, "pages", i => FirstViolation(i))
            ?? Str(x.LedgerEpoch, P4, null, "ledgerEpoch"),
        Ready x => Str(x.BridgeVersion, P5, null, "bridgeVersion"),
        Ping x => null,
        Pong x => Str(x.UploadDir, null, 1024, "uploadDir"),
        PairHello x => Int(x.ProtocolVersion, null, null, "protocolVersion")
            ?? Str(x.BrowserInstanceId, P1, null, "browserInstanceId")
            ?? Str(x.ExtNonce, P2, null, "extNonce"),
        PairWait x => null,
        PairProof x => Str(x.BridgeNonce, P2, null, "bridgeNonce")
