    private const long MaxSafeInteger = 9007199254740991;

    private static string? Str(string? value, Regex? re, int? maxLength, string name) =>
        value is null ? null
        : maxLength is { } max && value.Length > max ? $"{name} longer than {max}"
        : re is not null && !re.IsMatch(value) ? $"{name} does not match {re}"
        : null;

    private static string? Int(long? value, long? minimum, long? maximum, string name) =>
        value is null ? null
        : value is not (>= -MaxSafeInteger and <= MaxSafeInteger) ? $"{name} outside the safe integer range"
        : minimum is { } min && value < min ? $"{name} below {min}"
        : maximum is { } max && value > max ? $"{name} above {max}"
        : null;

    private static string? Each<T>(IReadOnlyList<T>? items, int maxItems, string name, Func<T, string?> check, int minItems = 0) =>
        items is null ? null
        : items.Count > maxItems ? $"{name} has more than {maxItems} items"
        : items.Count < minItems ? $"{name} has fewer than {minItems} items"
        : items.Select(i => i is null ? $"{name} contains null" : check(i)).FirstOrDefault(v => v is not null);
}
